// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        address user = address(0x1);
        vm.deal(user, amount);
        vm.prank(user);
        c.addToBalance{value: amount}();
        uint256 balBefore = c.getBalance(user);
        vm.prank(user);
        c.withdrawBalance();
        uint256 balAfter = c.getBalance(user);
        assertTrue(balAfter == 0);
    }
}
